#include <iostream>
#include <vector>
using namespace std;

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int Q;
  cin >> Q;
  vector<int> A{0}, B{0};
  for (int q = 1; q <= Q; q++) {
    int cmd;
    cin >> cmd;
    if (cmd == 1) {
      char c;
      cin >> c;
      A.push_back(A.back() + (c == '(' ? 1 : -1));
      B.push_back(min(B.back(), A.back()));
    } else {
      A.pop_back();
      B.pop_back();
    }
    cout << (A.back() == 0 and B.back() == 0 ? "Yes" : "No") << "\n";
  }
}
